frappe.ui.form.on('Expense Claim', {
	refresh(frm) {
		// 1. Check if the user has the 'Field Sales User' role
        if (frappe.user.has_role('Field Sales User')) {
            // 1. Initial toggle on load
            toggle_task_field(frm);
            // 2. Apply a filter to the 'payable_account' link field
            frm.set_query('payable_account', () => {
                return {
                    filters: {
                        'name': 'Expense Claims - SE-K'
                    }
                };
            });

            // 3. Optional: Set the value automatically if it's a new record
            if (frm.is_new()) {
                frm.set_value('payable_account', 'Expense Claims - SE-K');
            }
            // 4. Advanced Filter for Projects
            const project_filter = {
                filters: [
                    ['Project User', 'user', '=', frappe.session.user],
                    ['Project', 'status', '=', 'Open']
                ]
            };

            frm.set_query('project', () => project_filter);
            // The second argument 'expenses' targets the child table
            frm.set_query('project', 'expenses', () => project_filter);
            // 5. SET MANDATORY FIELDS
            frm.set_df_property('project', 'reqd', 1);
            frm.set_df_property('payable_account', 'reqd', 1);
            frm.set_df_property('task', 'reqd', 1);
            frm.set_df_property('clearance_date', 'read_only', 1);
            // 6. Filter Mode of Payment to show only "Credit"
            frm.set_query('mode_of_payment', () => {
                return {
                    filters: [
                        ['Mode of Payment', 'name', 'not like', '%Credit%']
                    ]
                };
            });
        }
	},
	// Triggered when the Project field is changed
    project(frm) {
        toggle_task_field(frm);

        // Clear task value if project is removed/changed to prevent data mismatch
        frm.set_value('task', '');
    }
})
var toggle_task_field = function(frm) {
    if (frm.doc.project) {
        frm.set_df_property('task', 'hidden', 0);
    } else {
        frm.set_df_property('task', 'hidden', 1);
    }
};

frappe.ui.form.on('Timesheet', {
	refresh: function(frm) {
	    // 1. Make Project mandatory on refresh
        frm.set_df_property('parent_project', 'reqd', 1);
        // 2. Filter the main Parent Project field on load
        if (frappe.user.has_role('Field Sales User')) {
            frm.set_query('parent_project', () => {
                return {
                    filters: [
                        ['Project User', 'user', '=', frappe.session.user],
                        ['Project', 'status', '=', 'Open']
                    ]
                };
            });
        }

        //3. Initial visibility check
        toggle_time_logs(frm);
    },

    parent_project: function(frm) {
        // 2. Triggered when the main Project field changes
        toggle_time_logs(frm);

        // Filter the 'project' field inside the child table to match the parent selection
        if (frm.doc.parent_project) {
            frm.set_query('project', 'time_logs', () => {
                return {
                    filters: {
                        'name': frm.doc.parent_project
                    }
                };
            });
        }
    }
})
// Helper function to handle visibility logic
var toggle_time_logs = function(frm) {
    if (frm.doc.parent_project) {
        frm.toggle_display('time_logs', true);
    } else {
        // Hide if no project is selected (if that is your requirement)
        frm.toggle_display('time_logs', false);
    }
};

frappe.ui.form.on('Social Login Key', {
    refresh: function(frm) {
        // Add the button only if the document is not new
        if (!frm.is_new()) {
            frm.add_custom_button(__('Set as Default'), function() {
                frappe.confirm(
                    __('Are you sure you want this Social Login key to be default for Login?'),
                    function() {
                        // Action if "Yes" is clicked
                        frappe.call({
                            method: "core_customizations.core_customizations.api.set_default_social_login",
                            args: {
                                "name": frm.doc.name
                            },
                            callback: function(r) {
                                if (!r.exc) {
                                    frm.reload_doc();
                                    frappe.msgprint(__('Success: This is now the default login key.'));
                                }
                            }
                        });
                    }
                );
            }, __('Actions'));
        }
    }
});

