frappe.ui.form.on("Delivery Note", {
	setup: function(frm) {
		// Set dynamic address queries filtered by Transporter
		frm.set_query("custom_transporter", function() {
			return { filters: { is_transporter: 1 } };
		});

		frm.set_query("custom_transporter_from_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter || ""
				}
			};
		});

		frm.set_query("custom_transporter_to_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_transporter || ""
				}
			};
		});
	},

	onload: function(frm) {
		if (frm.doc.company == "Sravi Enterprises - Kolapakkam" && !frm.doc.set_warehouse) {
			frm.set_value("set_warehouse", "Stores - SE-K");
		}
	},

	refresh: function(frm) {
		if (frm.is_new()) {
			return;
		}

		// 1. Logistics Button Group
		frm.page.add_inner_button(__("Transporter"), function() {
			open_transporter_dialog(frm);
		}, __("Logistics"));

		frm.page.add_inner_button(__("Update LR Details"), function() {
			open_lr_dialog(frm);
		}, __("Logistics"));

		// 2. Packing Slips Button Group
		frm.page.add_inner_button(__("Generate"), function() {
			open_packing_slip_generator(frm);
		}, __("Packing Slips"));

		frm.page.add_inner_button(__("Edit / Cancel"), function() {
			open_manage_packing_slips_dialog(frm);
		}, __("Packing Slips"));

		frm.page.add_inner_button(__("Print Single"), function() {
			open_print_packing_slip_dialog(frm);
		}, __("Packing Slips"));

		frm.page.add_inner_button(__("Print Bulk"), function() {
			print_bulk_packing_labels(frm);
		}, __("Packing Slips"));
	},

	custom_transporter: function(frm) {
		if (!frm.doc.custom_transporter) {
			frm.set_value("custom_transporter_from_address", "");
			frm.set_value("custom_transporter_from_address_display", "");
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_transporter_from_address: function(frm) {
		if (frm.doc.custom_transporter_from_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: { address_dict: frm.doc.custom_transporter_from_address },
				callback: function(res) {
					let raw_html = res.message || "";
					let clean_text = raw_html.replace(/<br\s*[/]?>/gi, "\n").replace(/<[^>]+>/g, "").trim();
					frm.set_value("custom_transporter_from_address_display", clean_text);
				}
			});
		} else {
			frm.set_value("custom_transporter_from_address_display", "");
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_is_godown_delivery: function(frm) {
		if (!frm.doc.custom_is_godown_delivery) {
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_transporter_to_address: function(frm) {
		if (frm.doc.custom_transporter_to_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: { address_dict: frm.doc.custom_transporter_to_address },
				callback: function(res) {
					let raw_html = res.message || "";
					let clean_text = raw_html.replace(/<br\s*[/]?>/gi, "\n").replace(/<[^>]+>/g, "").trim();
					frm.set_value("custom_transporter_to_address_display", clean_text);
				}
			});
		} else {
			frm.set_value("custom_transporter_to_address_display", "");
		}
	}
});

// ==========================================
// 1. Transporter Assignment & Edit Dialog
// ==========================================
function open_transporter_dialog(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_unpacked_items_summary",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message) return;
			let data = r.message;
			let current = data.current_transporter || {};
			let defaults = data.customer_defaults || {};

			let has_saved_logistics = !!(current.transporter && current.from_address);
			let init_transporter = current.transporter || defaults.default_transporter || "";
			let init_from_addr = has_saved_logistics ? (current.from_address || "") : (defaults.default_from_address || "");
			let init_is_godown = has_saved_logistics ? (current.is_godown_delivery || 0) : (defaults.default_is_godown || 0);
			let init_to_addr = init_is_godown ? (has_saved_logistics ? (current.to_address || "") : (defaults.default_to_address || "")) : "";

			let d = new frappe.ui.Dialog({
				title: __("Assign Transporter & Logistics Details"),
				fields: [
					{
						fieldtype: "Link",
						fieldname: "transporter",
						label: __("Transporter"),
						options: "Supplier",
						get_query: function() {
							return { filters: { is_transporter: 1 } };
						},
						default: init_transporter,
						onchange: function() {
							let t = d.get_value("transporter");
							d.set_value("from_address", "");
							d.set_value("is_godown_delivery", 0);
							d.set_value("to_address", "");
							d.set_df_property("is_godown_delivery", "hidden", 1);
							d.set_df_property("to_address", "hidden", 1);
							d.set_df_property("to_address_html", "hidden", 1);
							d.fields_dict.from_address_html.$wrapper.html("");
							d.fields_dict.to_address_html.$wrapper.html("");

							d.set_df_property("from_address", "get_query", function() {
								return {
									query: "frappe.contacts.doctype.address.address.address_query",
									filters: { link_doctype: "Supplier", link_name: t || "" }
								};
							});
							d.set_df_property("to_address", "get_query", function() {
								return {
									query: "frappe.contacts.doctype.address.address.address_query",
									filters: { link_doctype: "Supplier", link_name: t || "" }
								};
							});
						}
					},
					{
						fieldtype: "Link",
						fieldname: "from_address",
						label: __("Origin / Booking Hub Address"),
						options: "Address",
						default: init_from_addr,
						get_query: function() {
							let t = d.get_value("transporter");
							return {
								query: "frappe.contacts.doctype.address.address.address_query",
								filters: { link_doctype: "Supplier", link_name: t || "" }
							};
						},
						onchange: function() {
							let f = d.get_value("from_address");
							update_address_preview("from_address", "from_address_html", d, false);
							if (f) {
								d.set_df_property("is_godown_delivery", "hidden", 0);
							} else {
								d.set_df_property("is_godown_delivery", "hidden", 1);
								d.set_value("is_godown_delivery", 0);
								d.set_df_property("to_address", "hidden", 1);
								d.set_df_property("to_address_html", "hidden", 1);
								d.set_value("to_address", "");
							d.fields_dict.to_address_html.$wrapper.html("");
							}
						}
					},
					{
						fieldtype: "HTML",
						fieldname: "from_address_html"
					},
					{
						fieldtype: "Check",
						fieldname: "is_godown_delivery",
						label: __("Is Godown Delivery"),
						default: init_is_godown,
						hidden: !init_from_addr,
						onchange: function() {
							let is_g = d.get_value("is_godown_delivery");
							d.set_df_property("to_address", "hidden", !is_g);
							d.set_df_property("to_address", "reqd", !!is_g);
							d.set_df_property("to_address_html", "hidden", !is_g);
							if (is_g) {
								update_address_preview("to_address", "to_address_html", d, true);
							} else {
								d.set_value("to_address", "");
								d.fields_dict.to_address_html.$wrapper.html("");
							}
						}
					},
					{
						fieldtype: "Link",
						fieldname: "to_address",
						label: __("Destination Godown Address"),
						options: "Address",
						default: init_to_addr,
						hidden: !init_is_godown,
						reqd: !!init_is_godown,
						get_query: function() {
							let t = d.get_value("transporter");
							return {
								query: "frappe.contacts.doctype.address.address.address_query",
								filters: { link_doctype: "Supplier", link_name: t || "" }
							};
						},
						onchange: function() {
							update_address_preview("to_address", "to_address_html", d, true);
						}
					},
					{
						fieldtype: "HTML",
						fieldname: "to_address_html",
						hidden: !init_is_godown
					}
				],
				primary_action_label: __("Save Transporter Details"),
				primary_action: function(values) {
					if (values.is_godown_delivery && !values.to_address) {
						frappe.msgprint(__("Destination Godown Address is mandatory when Godown Delivery is selected."));
						return;
					}

					frappe.call({
						method: "core_customizations.core_customizations.delivery_note.update_transporter_details",
						args: {
							delivery_note: frm.doc.name,
							transporter: values.transporter,
							from_address: values.from_address,
							is_godown: values.is_godown_delivery ? 1 : 0,
							to_address: values.is_godown_delivery ? values.to_address : null
						},
						freeze: true,
						callback: function(res) {
							d.hide();
							frm.reload_doc();
							frappe.show_alert({ message: __("Transporter details updated successfully"), indicator: "green" });
						}
					});
				}
			});

			d.show();

			// Render initial address previews
			if (init_from_addr) {
				update_address_preview("from_address", "from_address_html", d, false);
			}
			if (init_is_godown && init_to_addr) {
				update_address_preview("to_address", "to_address_html", d, true);
			}
		}
	});
}

function update_address_preview(fieldname, html_fieldname, d, is_destination) {
	let addr_name = d.get_value(fieldname);
	if (!addr_name) {
		d.fields_dict[html_fieldname].$wrapper.html("");
		return;
	}

	frappe.call({
		method: "frappe.contacts.doctype.address.address.get_address_display",
		args: { address_dict: addr_name },
		callback: function(res) {
			let raw_html = res.message || "";
			let display = raw_html.replace(/<br\s*[/]?>/gi, ", ").replace(/<[^>]+>/g, "").replace(/\n+/g, ", ").trim();
			if (display) {
				let border_style = is_destination ? "border: 1.5px dashed #c53030; background-color: #fff5f5;" : "border: 1px solid #cbd5e0; background-color: #f7fafc;";
				let title = is_destination ? "📍 <b>Destination Godown:</b>" : "🏢 <b>Origin / Booking Hub:</b>";
				d.fields_dict[html_fieldname].$wrapper.html(`
					<div style="${border_style} border-radius: 4px; padding: 6px 10px; margin-top: 4px; margin-bottom: 6px; font-size: 12px; line-height: 1.4; color: #2d3748;">
						${title} ${display}
					</div>
				`);
			} else {
				d.fields_dict[html_fieldname].$wrapper.html("");
			}
		}
	});
}

