// 2. Dedicated LR Details Dialog
// ==========================================
function open_lr_dialog(frm) {
	let d = new frappe.ui.Dialog({
		title: __("Update Lorry Receipt (LR) Details"),
		fields: [
			{
				fieldtype: "Data",
				fieldname: "lr_no",
				label: __("LR / Consignment No"),
				default: frm.doc.lr_no,
				reqd: 1
			},
			{
				fieldtype: "Date",
				fieldname: "lr_date",
				label: __("LR Date"),
				default: frm.doc.lr_date || frappe.datetime.get_today(),
				reqd: 1
			}
		],
		primary_action_label: __("Save LR Details"),
		primary_action: function(values) {
			frappe.call({
				method: "core_customizations.core_customizations.delivery_note.update_lr_details",
				args: {
					delivery_note: frm.doc.name,
					lr_no: values.lr_no,
					lr_date: values.lr_date
				},
				freeze: true,
				callback: function(res) {
					d.hide();
					frm.reload_doc();
					frappe.show_alert({ message: __("LR Details updated successfully"), indicator: "green" });
				}
			});
		}
	});

	d.show();
}

// ==========================================
// 3. Interactive Packing Slip Generator
// ==========================================
function open_packing_slip_generator(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_unpacked_items_summary",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message) return;
			let data = r.message;
			let items = data.items || [];

			if (items.length === 0) {
				frappe.msgprint(__("No items found in Delivery Note"));
				return;
			}

			// Build item options with balance indication
			let item_options = items.map(function(i) {
				let bal_str = i.remaining_qty > 0 ? ` (Balance: ${i.remaining_qty} ${i.uom})` : ` (Fully Packed)`;
				return {
					label: `${i.item_code} - ${i.item_name}${bal_str}`,
					value: i.item_code
				};
			});
			item_options.push({ label: __("--- Mixed Items Carton ---"), value: "_MIXED_" });

			let d = new frappe.ui.Dialog({
				title: __("Generate Packing Slips (Box {0}+)", [data.next_package_no]),
				fields: [
					{
						fieldtype: "Select",
						fieldname: "selected_item",
						label: __("Select Item / Mixed Carton"),
						options: item_options,
						reqd: 1,
						onchange: function() {
							let sel = d.get_value("selected_item");
							if (sel === "_MIXED_") {
								d.set_df_property("single_item_section", "hidden", 1);
								d.set_df_property("mixed_items_section", "hidden", 0);
								d.set_df_property("qty_per_box", "reqd", 0);
							} else {
								d.set_df_property("single_item_section", "hidden", 0);
								d.set_df_property("mixed_items_section", "hidden", 1);
								d.set_df_property("qty_per_box", "reqd", 1);

								let itm = items.find(i => i.item_code === sel);
								if (itm) {
									d.set_value("qty_per_box", itm.case_pack || itm.remaining_qty || 1);
									let boxes_calc = (itm.case_pack && itm.remaining_qty > 0) ? Math.floor(itm.remaining_qty / itm.case_pack) : 1;
									d.set_value("no_of_boxes", Math.max(1, boxes_calc));
								}
							}
						}
					},
					{
						fieldtype: "Section Break",
						fieldname: "single_item_section",
						label: __("Single Item Box Settings")
					},
					{
						fieldtype: "Float",
						fieldname: "qty_per_box",
						label: __("Quantity per Box"),
						default: 1
					},
					{
						fieldtype: "Int",
						fieldname: "no_of_boxes",
						label: __("Number of Boxes to Generate"),
						default: 1,
						reqd: 1
					},
					{
						fieldtype: "Section Break",
						fieldname: "mixed_items_section",
						label: __("Mixed Carton Items Qty"),
						hidden: 1
					},
					{
						fieldtype: "HTML",
						fieldname: "mixed_items_html"
					}
				],
				primary_action_label: __("Generate Packing Slips"),
				primary_action: function(values) {
					let packing_type = values.selected_item === "_MIXED_" ? "mixed" : "single";
					let mixed_list = [];

					if (packing_type === "mixed") {
						items.forEach(function(i) {
							let input_val = flt(d.$wrapper.find(`.mixed-qty-input[data-item="${i.item_code}"]`).val());
							if (input_val > 0) {
								mixed_list.push({ item_code: i.item_code, qty: input_val });
							}
						});

						if (mixed_list.length === 0) {
							frappe.msgprint(__("Please enter quantity > 0 for at least one item"));
							return;
						}
					}

					frappe.call({
						method: "core_customizations.core_customizations.delivery_note.generate_packing_slips",
						args: {
							delivery_note: frm.doc.name,
							packing_type: packing_type,
							item_code: values.selected_item !== "_MIXED_" ? values.selected_item : null,
							qty_per_box: values.qty_per_box,
							no_of_boxes: values.no_of_boxes || 1,
							mixed_items: mixed_list
						},
						freeze: true,
						callback: function(res) {
							d.hide();
							frm.reload_doc();
							frappe.show_alert({ message: res.message.message, indicator: "green" });
						}
					});
				}
			});

			// Render mixed items table inside dialog
			let mixed_html = `
				<table class="table table-bordered table-sm" style="font-size: 12px; margin-top: 5px;">
					<thead>
						<tr style="background-color: #f4f5f7;">
							<th>${__("Item Code")}</th>
							<th>${__("Unpacked Balance")}</th>
							<th style="width: 140px;">${__("Qty in this Box")}</th>
						</tr>
					</thead>
					<tbody>
			`;
			items.forEach(function(i) {
				mixed_html += `
					<tr>
						<td><b>${i.item_code}</b><br><span class="text-muted">${i.item_name}</span></td>
						<td><span class="badge ${i.remaining_qty > 0 ? 'badge-warning' : 'badge-secondary'}">${i.remaining_qty} ${i.uom}</span></td>
						<td>
							<input type="number" class="form-control form-control-sm mixed-qty-input" data-item="${i.item_code}" value="${i.remaining_qty > 0 ? i.remaining_qty : 0}" min="0" max="${i.remaining_qty}">
						</td>
					</tr>
				`;
			});
			mixed_html += `</tbody></table>`;
			d.fields_dict.mixed_items_html.$wrapper.html(mixed_html);

			d.show();
			// Trigger initial change
			d.fields_dict.selected_item.set_value(item_options[0].value);
		}
	});
}

// ==========================================
// 4. Manage Packing Slips (Edit / Cancel) Dialog
// ==========================================
function open_manage_packing_slips_dialog(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_packing_slips_list",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message || r.message.length === 0) {
				frappe.msgprint(__("No Packing Slips found for this Delivery Note"));
				return;
			}
			let slips = r.message;

			let d = new frappe.ui.Dialog({
				title: __("Manage Packing Slips ({0} Total Boxes)", [slips.length]),
				fields: [
					{
						fieldtype: "HTML",
						fieldname: "slips_table_html"
					}
				],
				primary_action_label: __("Delete All Packing Slips"),
				primary_action: function() {
					frappe.confirm(
						__("Are you sure you want to delete ALL {0} Packing Slips for this Delivery Note?", [slips.length]),
						function() {
							frappe.call({
								method: "core_customizations.core_customizations.delivery_note.delete_packing_slips",
								args: { delivery_note: frm.doc.name },
								freeze: true,
								callback: function(res) {
									d.hide();
									frm.reload_doc();
									frappe.show_alert({ message: res.message.message, indicator: "orange" });
								}
							});
						}
					);
				}
			});

			let html = `
				<div style="max-height: 400px; overflow-y: auto;">
					<table class="table table-bordered table-sm" style="font-size: 12px;">
						<thead>
							<tr style="background-color: #f8f9fa;">
								<th style="width: 80px;">${__("Box No")}</th>
								<th style="width: 150px;">${__("Packing Slip")}</th>
								<th>${__("Packed Items")}</th>
								<th style="width: 70px;">${__("Action")}</th>
							</tr>
						</thead>
						<tbody>
			`;
			slips.forEach(function(s) {
				html += `
					<tr>
						<td style="font-weight: bold; text-align: center;">Box ${s.box_no}</td>
						<td><a href="/app/packing-slip/${s.name}" target="_blank"><b>${s.name}</b></a></td>
						<td>${s.items_display}</td>
						<td style="text-align: center;">
							<button class="btn btn-xs btn-danger delete-single-ps" data-ps="${s.name}">
								<i class="fa fa-trash"></i>
							</button>
						</td>
					</tr>
				`;
			});
			html += `</tbody></table></div>`;

			d.fields_dict.slips_table_html.$wrapper.html(html);

			// Attach single delete click handler
			d.$wrapper.on("click", ".delete-single-ps", function() {
				let ps_name = $(this).attr("data-ps");
				frappe.confirm(__("Delete Packing Slip {0}?", [ps_name]), function() {
					frappe.call({
						method: "core_customizations.core_customizations.delivery_note.delete_packing_slips",
						args: {
							delivery_note: frm.doc.name,
							packing_slip_names: JSON.stringify([ps_name])
						},
						freeze: true,
						callback: function(res) {
							d.hide();
							frm.reload_doc();
							frappe.show_alert({ message: res.message.message, indicator: "orange" });
						}
					});
				});
			});

			d.show();
		}
	});
}

// ==========================================
// 5. Print Single Packing Slip Selection Dialog
// ==========================================
function open_print_packing_slip_dialog(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_packing_slips_list",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message || r.message.length === 0) {
				frappe.msgprint(__("No Packing Slips generated yet. Please click 'Generate' first."));
				return;
			}
			let slips = r.message;

			let options = slips.map(function(s) {
				return {
					label: `Box ${s.box_no} (${s.name}) - ${s.items_display}`,
					value: s.name
				};
			});

			let d = new frappe.ui.Dialog({
				title: __("Select Packing Slip to Print"),
				fields: [
					{
						fieldtype: "Select",
						fieldname: "selected_ps",
						label: __("Select Box / Packing Slip"),
						options: options,
						default: options[0].value,
						reqd: 1
					}
				],
				primary_action_label: __("Print 4x6 Label"),
				primary_action: function(values) {
					d.hide();
					let print_url = frappe.urllib.get_full_url(
						`/printview?doctype=Packing%20Slip&name=${values.selected_ps}&trigger_print=1&format=Carton%20Shipping%20Label%20(4x6)&no_letterhead=1`
					);
					window.open(print_url, "_blank");
				}
			});

			d.show();
		}
	});
}

// ==========================================
// 6. Bulk Print All 4x6 Carton Labels
// ==========================================
function print_bulk_packing_labels(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_bulk_packing_labels_html",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message) return;
			let print_window = window.open("", "_blank");
			print_window.document.open();
			print_window.document.write(r.message);
			print_window.document.close();
			print_window.focus();
			setTimeout(function() {
				print_window.print();
			}, 500);
		}
	});
}

