	},

	custom_default_transporter_from_address: function(frm) {
		if (!frm.doc.custom_default_transporter_from_address) {
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_default_transporter_to_address", "");
		}
	},

	custom_is_godown_delivery: function(frm) {
		if (!frm.doc.custom_is_godown_delivery) {
			frm.set_value("custom_default_transporter_to_address", "");
